from AlgorithmImports import *
from collections import deque
import math


class IndependentDailyStrategies(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        # Supply the intended percentage as the "strategy_a_percentage" parameter.
        self.strategy_a_percentage = float(
            self.get_parameter("strategy_a_percentage") or "1.0"
        )

        self.closes = {ticker: deque(maxlen=101) for ticker in self.tickers}
        self.opens = {ticker: deque(maxlen=2) for ticker in self.tickers}

        self.a_lot = 0
        self.b_lot = 0
        self.a_round_trip_open = False
        self.b_round_trip_open = False

    def on_data(self, data: Slice):
        received = {}

        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bar = data.bars[symbol]
                received[ticker] = bar
                self.closes[ticker].append(bar.close)
                self.opens[ticker].append(bar.open)

        if len(received) != len(self.tickers):
            return

        if not self._all_history_ready():
            return

        # Sells are evaluated before buys.
        if self.a_lot > 0 and self._spy_crosses_below_sma100():
            self.market_order(self.symbols["SPY"], -self.a_lot)
            self.a_lot = 0
            self.a_round_trip_open = False

        if self.b_lot > 0 and self._aapl_rsi14() > 60:
            self.market_order(self.symbols["AAPL"], -self.b_lot)
            self.b_lot = 0
            self.b_round_trip_open = False

        if self.a_lot == 0 and self._spy_crosses_above_sma100():
            price = received["SPY"].close
            shares = int(math.floor(
                (self.portfolio.total_portfolio_value * self.strategy_a_percentage) / price
            ))
            if shares > 0:
                self.market_order(self.symbols["SPY"], shares)
                self.a_lot = shares
                self.a_round_trip_open = True

        if self.b_lot == 0 and self._aapl_red_streak() >= 3:
            price = received["AAPL"].close
            if self.portfolio.cash >= 20_000:
                shares = int(math.floor(20_000 / price))
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.b_lot = shares
                    self.b_round_trip_open = True

    def _all_history_ready(self):
        return (
            len(self.closes["SPY"]) >= 101 and
            len(self.closes["AAPL"]) >= 15
        )

    def _spy_sma100_today(self):
        values = list(self.closes["SPY"])
        return sum(values[-100:]) / 100.0

    def _spy_sma100_yesterday(self):
        values = list(self.closes["SPY"])
        return sum(values[-101:-1]) / 100.0

    def _spy_crosses_above_sma100(self):
        values = list(self.closes["SPY"])
        yesterday_close = values[-2]
        today_close = values[-1]
        return (
            yesterday_close <= self._spy_sma100_yesterday() and
            today_close > self._spy_sma100_today()
        )

    def _spy_crosses_below_sma100(self):
        values = list(self.closes["SPY"])
        yesterday_close = values[-2]
        today_close = values[-1]
        return (
            yesterday_close >= self._spy_sma100_yesterday() and
            today_close < self._spy_sma100_today()
        )

    def _aapl_red_streak(self):
        values = list(self.closes["AAPL"])
        streak = 0

        for i in range(len(values) - 1, 0, -1):
            if values[i] < values[i - 1]:
                streak += 1
            else:
                break

        return streak

    def _aapl_rsi14(self):
        values = list(self.closes["AAPL"])
        changes = [
            values[i] - values[i - 1]
            for i in range(len(values) - 14, len(values))
        ]

        average_gain = sum(max(change, 0) for change in changes) / 14.0
        average_loss = sum(max(-change, 0) for change in changes) / 14.0

        if average_loss == 0:
            return 100.0 if average_gain > 0 else 50.0

        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
